<?php require_once __DIR__.'/../config/config.php';role_required(['admin']);$pageTitle='Users';$pdo=db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$reqRole=$_POST['role']??'author';if($reqRole==='editor_in_chief'){ $cnt=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='editor_in_chief'")->fetchColumn(); if($cnt>=1){ $msg='An Editor-in-Chief account already exists.'; } } if(!$msg){$s=$pdo->prepare('INSERT INTO users(full_name,email,password_hash,role,affiliation,phone,orcid,expertise) VALUES(?,?,?,?,?,?,?,?)');try{$s->execute([$_POST['full_name'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT),$reqRole,$_POST['affiliation']??null,$_POST['phone']??null,$_POST['orcid']??null,$_POST['expertise']??null]);$msg='User created.';}catch(Exception $e){$msg='Unable to create user; check email.';}}}$rows=$pdo->query('SELECT id,full_name,email,role,active,created_at FROM users ORDER BY id DESC')->fetchAll();include __DIR__.'/../includes/header.php';?><h1 class="title">User Management</h1><div class="panel"><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="grid"><div><label>Name</label><input name="full_name" required></div><div><label>Email</label><input name="email" type="email" required></div><div><label>Password</label><input name="password" type="password" minlength="8" required></div><div><label>Role</label><select name="role"><?php foreach(['admin','editor_in_chief','editor','reviewer','author','production'] as $r):?><option><?=$r?></option><?php endforeach;?></select></div><div><label>Affiliation</label><input name="affiliation"></div><div><label>Expertise</label><input name="expertise"></div></div><button class="btn primary">Create User</button></form></div><div class="panel"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Active</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['active']?'Yes':'No')?></td></tr><?php endforeach;?></table></div><?php include __DIR__.'/../includes/footer.php';?>